INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_cooling', 'q1', 1, 'Is the outdoor unit running?', 'Tech listens + looks at condenser fan', 'yesno', NULL, NULL, NULL, '{"no": {"next_step_id": "q2-cap"}, "yes": {"phase_2_gate": true, "after": {"low_suction_high_superheat": {"resolve_card": 8, "photo_slots": [{"slot": "uv_dye_glow", "photo_type": "evidence", "instruction": "UV dye glow under blacklight — for homeowner PDF only.", "ai_prompt": null}]}, "high_discharge_dirty_airflow": {"resolve_card": 14, "photo_slots": [{"slot": "condenser_coil_face", "photo_type": "diagnostic", "instruction": "Face-on shot of condenser coil — capture full face.", "ai_prompt": "Grade dirt density on condenser coil face: clean / dirty / heavily_blocked. Note debris like leaves or cottonwood."}]}, "high_pressure_high_subcooling": {"resolve_card": 17, "photo_slots": []}, "normal_pressures_warm_supply": {"resolve_card": 13, "photo_slots": []}}}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_cooling', 'q2-cap', 2, 'Open electrical panel. Enter capacitor µF reading.', 'Nameplate µF spec already loaded from Step Zero. App compares vs spec instantly.', 'reading', NULL, '{"type": "uF", "unit": "µF", "compare_to": "nameplate.cap_uf", "tolerance_pct": 10, "placeholder": "Read µF on tester"}'::jsonb, NULL, '{"low": {"resolve_card": 1, "photo_slots": [{"slot": "capacitor_can", "photo_type": "evidence", "instruction": "Side shot of capacitor showing brand + can.", "ai_prompt": null}]}, "ok": {"next_step_id": "q3-contactor"}, "high": {"resolve_card": 1, "photo_slots": [{"slot": "capacitor_can", "photo_type": "evidence", "instruction": "Side shot of capacitor showing brand + can.", "ai_prompt": null}]}}'::jsonb, '{"card_id": 1, "prompt": "After replacing capacitor, did the unit start and cool normally?", "yes_label": "YES - Fixed it", "no_label": "NO - Another issue"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_cooling', 'q3-contactor', 3, 'Photograph the contactor contact face and read voltage at L1 + L2.', 'Pitting, carbon, burn marks on contact face are diagnostic. Voltage reading confirms.', 'multi', '[{"kind": "photo", "spec": {"slot_name": "contactor_face", "photo_type": "diagnostic", "instruction": "Shoot the contact surface directly. Pitting, carbon, burn marks are visually clear here.", "ai_prompt": "Classify contact face condition: clean / pitted / arced / welded."}}, {"kind": "reading", "spec": {"type": "voltage", "unit": "V", "subtype": "L1_L2", "compare_to": null, "placeholder": "V at L1+L2 under load"}}]'::jsonb, NULL, NULL, '{"power_doesnt_pass": {"resolve_card": 3, "photo_slots": []}, "power_passes_normal": {"resolve_card": 15, "escalate": true, "reason": "contactor and uF both ok - control board / tech judgment"}}'::jsonb, '{"card_id": 3, "prompt": "After replacing contactor, did the unit run normally?", "yes_label": "YES - Fixed it", "no_label": "NO - Another issue"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('water_dripping', 'q1', 1, 'Where is water coming from?', NULL, 'visual_select', '[{"value": "indoor_drain_pan", "label": "Indoor - drain pan / unit", "icon": "drop"}, {"value": "outdoor_refrigerant", "label": "Outdoor - refrigerant lines", "icon": "snowflake"}]'::jsonb, NULL, NULL, '{"indoor_drain_pan": {"next_step_id": "q2-pan-photo"}, "outdoor_refrigerant": {"phase_2_gate": true, "after": {"low_suction_high_superheat": {"resolve_card": 8, "photo_slots": [{"slot": "uv_dye_glow", "photo_type": "evidence", "instruction": "UV dye glow under blacklight.", "ai_prompt": null}]}}}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('water_dripping', 'q2-pan-photo', 2, 'Photograph drain pan and condensate exit point.', 'Photo IS the diagnosis. Standing water + algae visible. Blocked exit confirms clog.', 'multi', '[{"kind": "photo", "spec": {"slot_name": "drain_pan_water", "photo_type": "diagnostic", "instruction": "Drain pan top-down - show standing water if present.", "ai_prompt": "Detect standing water + algae in drain pan. Classes: dry / damp / standing_water / overflowing."}}, {"kind": "photo", "spec": {"slot_name": "drain_exit_point", "photo_type": "diagnostic", "instruction": "Outdoor condensate exit point - show flow or blockage.", "ai_prompt": "Detect water flow at condensate exit. Classes: flowing / blocked."}}]'::jsonb, NULL, NULL, '{"pan_water_present_or_exit_blocked": {"resolve_card": 5, "photo_slots": []}, "pan_dry_and_exit_flowing": {"next_step_id": "q3-freeze-check"}}'::jsonb, '{"card_id": 5, "prompt": "After flushing drain, did water stop dripping?", "yes_label": "YES - Stopped", "no_label": "NO - Still dripping"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('water_dripping', 'q3-freeze-check', 3, 'Photograph filter + evaporator coil. Enter delta-T (supply minus return).', 'Dirty filter causes restricted airflow, coil freeze, melt, then drip.', 'multi', '[{"kind": "photo", "spec": {"slot_name": "filter_evaporator_coil", "photo_type": "diagnostic", "instruction": "Filter and evaporator coil face. Frost would be visible on coil.", "ai_prompt": "Detect filter dirt density (clean/dirty/replace) and frost on evaporator coil (dry/frost_present/heavy_frost)."}}, {"kind": "reading", "spec": {"type": "delta_T", "unit": "F", "compare_to": null, "placeholder": "supply minus return"}}]'::jsonb, NULL, NULL, '{"delta_T_low": {"resolve_card": 9, "photo_slots": []}, "delta_T_ok": {"resolve_card": 15, "escalate": true, "reason": "Pan dry, exit flowing, delta-T ok - water source not identified, manual diagnosis"}}'::jsonb, '{"card_id": 9, "prompt": "After fixing the airflow / refrigerant issue, did the dripping stop?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_turning_on', 'q1', 1, 'Any power at all? Check breaker, thermostat display, indoor lights.', NULL, 'yesno', NULL, NULL, NULL, '{"no": {"next_step_id": "q2-no-power"}, "yes": {"next_step_id": "q3-error-code"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_turning_on', 'q2-no-power', 2, 'Photograph contactor face and read voltage at L1 + L2.', NULL, 'multi', '[{"kind": "photo", "spec": {"slot_name": "contactor_face", "photo_type": "diagnostic", "instruction": "Contactor contact face close-up.", "ai_prompt": "Classify contact face: clean / pitted / arced / welded."}}, {"kind": "reading", "spec": {"type": "voltage", "unit": "V", "subtype": "L1_L2", "placeholder": "V at L1+L2"}}]'::jsonb, NULL, NULL, '{"power_reaches_doesnt_pass": {"resolve_card": 3}, "no_power_at_all": {"escalate": true, "reason": "Check breaker / disconnect"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_turning_on', 'q3-error-code', 3, 'Is there an error code on the control board?', NULL, 'yesno', NULL, NULL, NULL, '{"yes": {"next_step_id": "q4-board-photo"}, "no": {"next_step_id": "q5-cap-reading"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_turning_on', 'q4-board-photo', 4, 'Photograph the control board LED indicator showing the error pattern.', 'Get the LED indicator clearly in the frame. Solid colors and flash patterns both work.', 'photo', NULL, NULL, '{"slot_name": "control_board_led", "photo_type": "diagnostic", "instruction": "Get the LED indicator clearly in the frame. Solid colors and flash patterns both work.", "ai_prompt": "Read flash count or alphanumeric error code from control board photo. Output the literal code (e.g. E5, 4-flash)."}'::jsonb, '{"any": {"resolve_card": 7}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_turning_on', 'q5-cap-reading', 5, 'Enter capacitor µF reading.', NULL, 'reading', NULL, '{"type": "uF", "unit": "µF", "compare_to": "nameplate.cap_uf", "tolerance_pct": 10}'::jsonb, NULL, '{"low": {"resolve_card": 1, "photo_slots": [{"slot": "capacitor_can", "photo_type": "evidence", "instruction": "Side shot of capacitor.", "ai_prompt": null}]}, "ok": {"escalate": true, "reason": "Reading clean - manual diagnosis needed"}, "high": {"resolve_card": 1, "photo_slots": [{"slot": "capacitor_can", "photo_type": "evidence", "instruction": "Side shot of capacitor.", "ai_prompt": null}]}}'::jsonb, '{"card_id": 1, "prompt": "After replacing capacitor, did the unit start normally?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('making_noise', 'q1', 1, 'Select the noise type.', NULL, 'visual_select', '[{"value": "clicking", "label": "Clicking", "icon": "bell"}, {"value": "squealing", "label": "Squealing", "icon": "loud"}, {"value": "banging", "label": "Banging", "icon": "boom"}, {"value": "hissing", "label": "Hissing", "icon": "wind"}, {"value": "grinding", "label": "Grinding", "icon": "gear"}]'::jsonb, NULL, NULL, '{"clicking": {"next_step_id": "q2-cap-clicking"}, "squealing": {"next_step_id": "q3-blower"}, "banging": {"next_step_id": "q4-compressor"}, "hissing": {"phase_2_gate": true, "after": {"low_suction_high_superheat": {"resolve_card": 8}}}, "grinding": {"next_step_id": "q5-contactor"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('making_noise', 'q2-cap-clicking', 2, 'Enter capacitor µF reading.', NULL, 'reading', NULL, '{"type": "uF", "unit": "µF", "compare_to": "nameplate.cap_uf", "tolerance_pct": 10}'::jsonb, NULL, '{"low": {"resolve_card": 1, "photo_slots": [{"slot": "capacitor_can", "photo_type": "evidence"}]}, "ok": {"escalate": true, "reason": "Capacitor reading clean despite clicking - investigate"}}'::jsonb, '{"card_id": 1, "prompt": "After replacing capacitor, did clicking stop?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('making_noise', 'q3-blower', 3, 'Photograph blower wheel and read amp draw.', NULL, 'multi', '[{"kind": "photo", "spec": {"slot_name": "blower_wheel", "photo_type": "diagnostic", "instruction": "Indoor blower wheel - show debris, worn blades, bearing.", "ai_prompt": "Detect: debris on blades / worn blade edges / bearing wear. Classes: clean / debris_present / worn / damaged."}}, {"kind": "reading", "spec": {"type": "amps_blower", "unit": "A", "compare_to": "nameplate.fla_blower", "tolerance_pct": 10}}]'::jsonb, NULL, NULL, '{"over_fla": {"resolve_card": 4}, "ok": {"escalate": true, "reason": "Blower amps ok, photo ok - escalate"}}'::jsonb, '{"card_id": 4, "prompt": "After repair, did squealing stop?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('making_noise', 'q4-compressor', 4, 'Read compressor amp draw and capture exterior photo (PDF only).', NULL, 'multi', '[{"kind": "reading", "spec": {"type": "amps_compressor", "unit": "A", "compare_to": "nameplate.rla", "tolerance_pct": 10}}, {"kind": "photo", "spec": {"slot_name": "compressor_exterior", "photo_type": "evidence", "instruction": "Compressor exterior - for homeowner PDF only.", "ai_prompt": null}}]'::jsonb, NULL, NULL, '{"over_rla": {"resolve_card": 10, "escalate": true, "reason": "Compressor over-amping - tech judgment"}, "ok": {"escalate": true, "reason": "Compressor amps ok - investigate noise source"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('making_noise', 'q5-contactor', 5, 'Photograph contactor contact face.', NULL, 'photo', NULL, NULL, '{"slot_name": "contactor_face", "photo_type": "diagnostic", "instruction": "Contact face close-up.", "ai_prompt": "Classify: clean / pitted / arced / welded."}'::jsonb, '{"pitted_or_arced": {"resolve_card": 3}, "clean": {"escalate": true, "reason": "Contactor visually clean - investigate"}}'::jsonb, '{"card_id": 3, "prompt": "After replacing contactor, did grinding stop?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('high_electric_bill', 'q1', 1, 'Is the unit running constantly / not cycling off?', NULL, 'yesno', NULL, NULL, NULL, '{"yes": {"next_step_id": "q2-filter-photo"}, "no": {"next_step_id": "q3-coil-photo"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('high_electric_bill', 'q2-filter-photo', 2, 'Photograph air filter face.', 'Air filter face-on shot. Capture entire filter face.', 'photo', NULL, NULL, '{"slot_name": "filter_face", "photo_type": "diagnostic", "instruction": "Air filter face-on shot. Capture entire filter face.", "ai_prompt": "Grade filter dirt density: clean / dirty / replace. Replace = visibly clogged, low light pass-through."}'::jsonb, '{"dirty_or_replace": {"resolve_card": 2}, "clean": {"resolve_card": 18, "escalate": true, "reason": "Filter clean but running constantly - load calc / undersizing investigation"}}'::jsonb, '{"card_id": 2, "prompt": "Was replacing the filter the primary fix?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('high_electric_bill', 'q3-coil-photo', 3, 'Photograph condenser coil. Enter discharge pressure and delta-T.', NULL, 'multi', '[{"kind": "photo", "spec": {"slot_name": "condenser_coil_face", "photo_type": "diagnostic", "instruction": "Face-on shot of condenser coil.", "ai_prompt": "Grade coil dirt density: clean / dirty / heavily_blocked."}}, {"kind": "reading", "spec": {"type": "pressure_psi", "subtype": "discharge", "unit": "PSI"}}, {"kind": "reading", "spec": {"type": "delta_T", "unit": "F"}}]'::jsonb, NULL, NULL, '{"coil_dirty_or_high_discharge": {"resolve_card": 14}, "all_clean": {"escalate": true, "reason": "Coil clean, normal pressure - Tech Judgment"}}'::jsonb, '{"card_id": 14, "prompt": "After cleaning coil, did the bill drop?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('error_code', 'q1', 1, 'Photograph the error code display or LED board.', 'Get the LED indicator or alphanumeric display clearly in frame.', 'photo', NULL, NULL, '{"slot_name": "control_board_led", "photo_type": "diagnostic", "instruction": "Get the LED indicator or alphanumeric display clearly in frame.", "ai_prompt": "Read flash count or alphanumeric error code. Output literal code (e.g. E5, 4-flash, U4, CH05). If LED is flashing, count the flashes."}'::jsonb, '{"extract_then_lookup": {"action": "call_error_code_lookup", "brand_from": "ocr_nameplate.brand", "code_from": "this_photo_ai_output", "after": {"pressure_sensor_fault": {"next_step_id": "q2-ohm-test"}, "refrigerant_low": {"phase_2_gate": true, "after": {"low_suction_high_superheat": {"resolve_card": 8}, "piston_pattern": {"resolve_card": 15}}}, "communication_fault": {"next_step_id": "q3-wiring"}, "lockout_trip": {"next_step_id": "q4-reset"}, "capacitor": {"resolve_card": 1, "photo_slots": [{"slot": "capacitor_can", "photo_type": "evidence"}]}, "contactor": {"resolve_card": 3}, "nuisance_or_unknown": {"next_step_id": "q4-reset"}}}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('error_code', 'q2-ohm-test', 2, 'Read ohms on the suspect sensor.', NULL, 'reading', NULL, '{"type": "ohms", "unit": "ohm", "compare_to": null, "placeholder": "ohms from sensor"}'::jsonb, NULL, '{"out_of_spec": {"resolve_card": 7}, "in_spec": {"escalate": true}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('error_code', 'q3-wiring', 3, 'Photograph terminal strip and read voltage drop.', NULL, 'multi', '[{"kind": "photo", "spec": {"slot_name": "terminal_strip", "photo_type": "diagnostic", "instruction": "Terminal strip - show burn marks or loose wires.", "ai_prompt": "Detect burn marks, loose terminals, or carbon."}}, {"kind": "reading", "spec": {"type": "voltage_drop", "subtype": "across_terminal", "unit": "V"}}]'::jsonb, NULL, NULL, '{"fault_confirmed": {"resolve_card": 6}, "clean": {"escalate": true, "reason": "Wiring clean - re-check error code"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('error_code', 'q4-reset', 4, 'After resetting the breaker, does the unit start?', NULL, 'yesno', NULL, NULL, NULL, '{"yes": {"resolve_card": 7, "note": "Nuisance trip"}, "no": {"jump_to_complaint": "intermittent_shutdown", "note": "Lockout returns - re-routing to Tab H"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_heating', 'q1-system-type', 1, 'System type (auto-detected from Step Zero nameplate).', 'Heat pump / gas furnace / dual fuel - no manual selection needed.', 'auto', NULL, NULL, NULL, '{"use_field": "ocr_nameplate.system_type", "heat_pump": {"phase_2_gate": true, "mode": "heating", "after": {"valve_stuck_cool": {"resolve_card": 12, "photo_slots": []}, "low_suction_heat_mode": {"resolve_card": 15, "photo_slots": [{"slot": "piston_bore", "photo_type": "evidence", "instruction": "Piston bore close-up - for PDF.", "ai_prompt": null}]}, "normal_pressure_heat": {"resolve_card": 7, "photo_slots": []}}}, "gas_furnace": {"next_step_id": "q2-burner-ignite"}, "dual_fuel": {"escalate": true, "reason": "Dual fuel - manual mode selection (out of Phase 3 scope)"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_heating', 'q2-burner-ignite', 2, 'Does the burner ignite?', NULL, 'visual_select', '[{"value": "no", "label": "No ignition"}, {"value": "yes_then_off", "label": "Ignites then shuts off"}]'::jsonb, NULL, NULL, '{"no": {"next_step_id": "q3-ignitor"}, "yes_then_off": {"next_step_id": "q4-flame-sensor"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_heating', 'q3-ignitor', 3, 'Photograph hot surface ignitor and read ohms / voltage.', NULL, 'multi', '[{"kind": "photo", "spec": {"slot_name": "ignitor_rod", "photo_type": "diagnostic", "instruction": "Hot surface ignitor element - show full rod.", "ai_prompt": "Detect crack in hot surface ignitor element. Classes: intact / hairline_crack / broken."}}, {"kind": "reading", "spec": {"type": "ohms", "unit": "ohm", "placeholder": "50-80 ohms healthy, open=cracked"}}, {"kind": "reading", "spec": {"type": "voltage", "subtype": "across_ignitor", "unit": "V"}}]'::jsonb, NULL, NULL, '{"cracked_or_open_ohms": {"resolve_card": 11}, "intact_and_normal": {"escalate": true, "reason": "Ignitor good - investigate gas valve / control"}}'::jsonb, '{"card_id": 11, "prompt": "After replacing ignitor, did burner light?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('not_heating', 'q4-flame-sensor', 4, 'Photograph flame sensor and read micro-amps.', NULL, 'multi', '[{"kind": "photo", "spec": {"slot_name": "flame_sensor_rod", "photo_type": "diagnostic", "instruction": "Flame sensor rod - show full surface.", "ai_prompt": "Detect oxide coating on flame sensor. Classes: clean / light_oxide / heavy_oxide."}}, {"kind": "reading", "spec": {"type": "micro_amps", "unit": "uA", "placeholder": ">2 uA healthy, <1 uA replace"}}]'::jsonb, NULL, NULL, '{"heavy_oxide_or_low_uA": {"resolve_card": 11}, "light_oxide_marginal_uA": {"escalate": true, "reason": "Clean and retest"}, "clean_and_high_uA": {"escalate": true, "reason": "Flame sensor good - investigate gas pressure / valve"}}'::jsonb, '{"card_id": 11, "prompt": "After cleaning flame sensor, did burner stay lit?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('intermittent_shutdown', 'q1', 1, 'Do you have a thermal camera on this call?', 'Path A (camera) is 2 steps. Path B (no camera) is 4 steps with 85-90% catch rate.', 'yesno', NULL, NULL, NULL, '{"yes": {"next_step_id": "q2-thermal-photo"}, "no": {"next_step_id": "q3-visual-photo"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('intermittent_shutdown', 'q2-thermal-photo', 2, 'Upload thermal image of all terminals - full compartment.', NULL, 'photo', NULL, NULL, '{"slot_name": "thermal_terminals", "photo_type": "diagnostic", "instruction": "Capture thermal image with FLIR or smartphone thermal attachment, then upload here.", "ai_prompt": "Detect hot spots in thermal image. Threshold: any pixel >20F above ambient = hotspot. Output: hotspot_count + max_delta_F."}'::jsonb, '{"hotspot_present": {"resolve_card": 16}, "no_hotspot": {"escalate": true, "reason": "No hotspot - re-route to Card #17 overcharge or #18 undersizing"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('intermittent_shutdown', 'q3-visual-photo', 3, 'Photograph terminal strip - visual inspection.', NULL, 'photo', NULL, NULL, '{"slot_name": "terminal_strip_visual", "photo_type": "diagnostic", "instruction": "Full terminal compartment - show all screws and wires.", "ai_prompt": "YOLO: detect burn marks, carbon, discoloration on terminals. Output: terminals_with_visual_signs."}'::jsonb, '{"any": {"next_step_id": "q4-ir-readings"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('intermittent_shutdown', 'q4-ir-readings', 4, 'Read terminal temperatures with IR point thermometer (one per terminal).', NULL, 'reading', NULL, '{"type": "temp_F", "subtype": "terminal_n", "unit": "F", "placeholder": "Enter terminal 1, 2, 3...", "multi_value": true}'::jsonb, NULL, '{"max_delta_over_10F": {"next_step_id": "q5-voltage-drop"}, "all_within_10F": {"next_step_id": "q5-voltage-drop"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('intermittent_shutdown', 'q5-voltage-drop', 5, 'Read voltage drop across the suspect terminal under load.', NULL, 'reading', NULL, '{"type": "voltage_drop", "subtype": "across_suspect_terminal", "unit": "V", "placeholder": ">3V = fault confirmed"}'::jsonb, NULL, '{"fault": {"resolve_card": 16, "note": "Path B confirmed"}, "elevated_or_ok": {"escalate": true, "reason": "Path B caps at 85-90%. FLIR One ~$400 ROI: 1 avoided $2-4k misdiag = 5-10x payback."}}'::jsonb, '{"card_id": 16, "prompt": "After retorque/clean, did intermittent shutdown stop?"}'::jsonb, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-1-filter', 1, 'Photograph air filter face.', NULL, 'photo', NULL, NULL, '{"slot_name": "filter_face", "photo_type": "diagnostic", "instruction": "Filter face-on. Show entire filter.", "ai_prompt": "Grade filter dirt density: clean / dirty / replace."}'::jsonb, '{"clean": {"finding": null, "next_step_id": "svc-2-cap"}, "dirty": {"finding": {"line_item_code": "filter_replacement", "amount_min": 18, "amount_max": 45, "card_id": 2}, "next_step_id": "svc-2-cap"}, "replace": {"finding": {"line_item_code": "filter_replacement", "amount_min": 18, "amount_max": 45, "card_id": 2}, "next_step_id": "svc-2-cap"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-2-cap', 2, 'Enter capacitor µF reading.', NULL, 'reading', NULL, '{"type": "uF", "unit": "µF", "compare_to": "nameplate.cap_uf", "tolerance_pct": 10}'::jsonb, NULL, '{"low": {"finding": {"line_item_code": "card_1_addon", "card_id": 1, "note": "Preventive replacement before peak summer"}, "next_step_id": "svc-3-coil"}, "ok": {"finding": null, "next_step_id": "svc-3-coil"}, "high": {"finding": {"line_item_code": "card_1_addon", "card_id": 1}, "next_step_id": "svc-3-coil"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-3-coil', 3, 'Photograph condenser coil face.', NULL, 'photo', NULL, NULL, '{"slot_name": "condenser_coil_face", "photo_type": "diagnostic", "instruction": "Coil face-on shot.", "ai_prompt": "Grade coil dirt density: clean / dirty / heavily_blocked."}'::jsonb, '{"clean": {"finding": null, "next_step_id": "svc-4-drain"}, "dirty": {"finding": {"line_item_code": "coil_cleaning", "amount_min": 80, "amount_max": 150}, "next_step_id": "svc-4-drain"}, "heavily_blocked": {"finding": {"line_item_code": "coil_cleaning", "amount_min": 80, "amount_max": 150}, "next_step_id": "svc-4-drain"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-4-drain', 4, 'Drain flush completed? Photograph drain pan after flush.', NULL, 'multi', '[{"kind": "visual_select", "spec": {"question_text": "Drain flushed?", "options": [{"value": "yes", "label": "YES"}, {"value": "no", "label": "Skipped"}]}}, {"kind": "photo", "spec": {"slot_name": "drain_pan_after", "photo_type": "evidence", "instruction": "Drain pan after flush - for homeowner PDF.", "ai_prompt": null}}]'::jsonb, NULL, NULL, '{"flushed": {"finding": {"line_item_code": "flush_tablet", "amount_min": 12, "amount_max": 18}, "next_step_id": "svc-5-terminals"}, "skipped": {"finding": null, "next_step_id": "svc-5-terminals"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-5-terminals', 5, 'Photograph terminal strip after retorque. Read voltage drop on main terminals.', NULL, 'multi', '[{"kind": "photo", "spec": {"slot_name": "terminal_strip_after", "photo_type": "evidence", "instruction": "Terminal strip after retorque - for PDF.", "ai_prompt": null}}, {"kind": "reading", "spec": {"type": "voltage_drop", "unit": "V", "placeholder": ">1V triggers Card #16 add-on"}}]'::jsonb, NULL, NULL, '{"voltage_drop_above_1V": {"finding": {"line_item_code": "card_16_addon", "card_id": 16, "note": "Loose terminal - recommend repair"}, "next_step_id": "svc-6-amps"}, "voltage_drop_ok": {"finding": null, "next_step_id": "svc-6-amps"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-6-amps', 6, 'Read compressor amp draw and blower amp draw.', NULL, 'multi', '[{"kind": "reading", "spec": {"type": "amps_compressor", "unit": "A", "compare_to": "nameplate.rla", "tolerance_pct": 10}}, {"kind": "reading", "spec": {"type": "amps_blower", "unit": "A", "compare_to": "nameplate.fla_blower", "tolerance_pct": 10}}]'::jsonb, NULL, NULL, '{"over_rla": {"finding": {"line_item_code": "flag_over_amping", "note": "Compressor over-amping - schedule assessment"}, "next_step_id": "svc-7-deltaT"}, "over_fla": {"finding": {"line_item_code": "flag_over_amping_blower", "note": "Blower over-FLA"}, "next_step_id": "svc-7-deltaT"}, "ok": {"finding": null, "next_step_id": "svc-7-deltaT"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-7-deltaT', 7, 'Read supply air temp and return air temp. App computes delta-T.', NULL, 'multi', '[{"kind": "reading", "spec": {"type": "temp_F", "subtype": "supply_air", "unit": "F"}}, {"kind": "reading", "spec": {"type": "temp_F", "subtype": "return_air", "unit": "F"}}]'::jsonb, NULL, NULL, '{"delta_low": {"finding": {"line_item_code": "flag_low_deltaT", "note": "Refrigerant or airflow issue - recommend follow-up Tab A"}, "next_step_id": "svc-8-run"}, "delta_ok": {"finding": null, "next_step_id": "svc-8-run"}, "delta_high": {"finding": {"note": "Over-cooling - possible low airflow"}, "next_step_id": "svc-8-run"}}'::jsonb, NULL, FALSE);
INSERT INTO diagnostic_questions (complaint_type, step_id, step_order, question_text, hint_text, input_type, options_jsonb, reading_spec, photo_spec, branch_logic_jsonb, data_collect_jsonb, is_terminal) VALUES ('service', 'svc-8-run', 8, 'Photograph system running with date/time visible.', 'System running - date/time stamp visible. This is the PDF cover photo.', 'photo', NULL, NULL, '{"slot_name": "system_running", "photo_type": "evidence", "instruction": "System running - date/time stamp visible. PDF cover photo.", "ai_prompt": null}'::jsonb, '{"any": {"service_complete": true, "generate_estimate": true, "finding": null}}'::jsonb, NULL, TRUE);
